exceptions = []
def log(case_ref, table, column, value, issue, severity="ACTION"):
    exceptions.append({"severity": severity, "caseReference": case_ref, "table": table, "column": column,
                       "value": None if value is None else str(value)[:300], "issue": issue})

def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() in ("", "nan", "None", "NaT")

def norm(v):
    return re.sub(r"[^a-z0-9]", "", str(v).lower())

GUID_NS = uuid.uuid5(uuid.NAMESPACE_URL, "pins-s62a-migration")
def make_guid(*parts):
    return str(uuid.uuid5(GUID_NS, "|".join(str(p) for p in parts))).upper()

LOOKUP = {}
for t, rows in REF.items():
    idx = {}
    for i, d in rows:
        for key in (norm(i), norm(d)):
            idx.setdefault(key, i)
        m = re.search(r"\(([^)]+)\)", d)
        if m:
            idx.setdefault(norm(m.group(1)), i)
    LOOKUP[t] = idx

enum_raw = pd.read_excel(enum_path, sheet_name=0, dtype=str).iloc[:, [0, 4, 5]]
enum_raw.columns = ["field", "horizon", "mpa"]
enum_raw["field"] = enum_raw["field"].ffill().str.strip()
ENUMS = {}
for _, r in enum_raw.dropna(subset=["horizon"]).iterrows():
    for h in str(r.horizon).split("\n"):
        h = re.sub(r"\s*\(\d+\)\s*$", "", h).strip()
        if h:
            ENUMS.setdefault(r.field, {})[norm(h)] = None if pd.isna(r.mpa) else re.sub(r"\s+", " ", str(r.mpa)).strip()

def advice_rule(v):
    t = str(v).strip().lower()
    if t in ("", "`"):
        return None
    if t.startswith("no"):
        return "No"
    if "pins" in t:
        return "Yes - PINS"
    if any(k in t for k in ("lpa", "udc", "council")):
        return "Yes - Council"
    return v

def resolve(ref_table, value, case_ref, table, column, enum_field=None, other_fallback=False, provisional=False):

    if blank(value):
        return None
    if value in VALUE_OVERRIDES.get(column, {}):
        return VALUE_OVERRIDES[column][value]
    idx = LOOKUP[ref_table]
    hit = idx.get(norm(value))
    if hit is None and enum_field:
        mapped = ENUMS.get(enum_field, {}).get(norm(value))
        if mapped and not mapped.startswith(("?", '"', "'")) and "??" not in mapped:
            hit = idx.get(norm(mapped))
            if hit is None and other_fallback and mapped.lower().startswith("other"):
                hit = idx.get("other")
    if hit is None and other_fallback and str(value).lower().startswith("other"):
        hit = idx.get("other")
    if hit is None:
        log(case_ref, table, column, value, f"No {ref_table} id for this value, left null")
    elif provisional:
        log(case_ref, table, column, value, f"Provisional {ref_table} id '{hit}', confirm against seed data", "INFO")
    return hit

def to_bool(v, case_ref=None, table=None, column=None):
    if blank(v):
        return None
    t = str(v).strip().lower()
    if t in ("yes", "y", "true", "1") or t.startswith("cil liab"):
        return True
    if t in ("no", "n", "false", "0"):
        return False
    log(case_ref, table, column, v, "Not a yes/no value, left null")
    return None

def to_num(v, case_ref=None, table=None, column=None, integer=False):
    if blank(v):
        return None
    try:
        n = float(re.sub(r"[£,\s]", "", str(v)).rstrip("."))
    except ValueError:
        m = re.search(r"-?\d[\d,]*\.?\d*", str(v))
        if not m:
            log(case_ref, table, column, v, "Not a number, left null")
            return None
        n = float(m.group(0).replace(",", "").rstrip("."))
        log(case_ref, table, column, v, f"Took the first number ({n}) from text", "INFO")
    return int(round(n)) if integer else n

def name_lookup(ref_df, name, case_ref, table, column):

    if blank(name):
        return None
    if ref_df is None:
        log(case_ref, table, column, name, "Reference file missing, id left null")
        return None
    parts = [p.strip() for p in re.split(r"[/&;,]| and ", str(name)) if p.strip()]
    first = parts[0]
    if len(parts) > 1:
        log(case_ref, table, column, name, f"Several names in one cell, used '{first}'", "INFO")
    names = ref_df["name"].map(norm)
    exact = ref_df[names == norm(first)]
    if len(exact) == 1:
        return exact.iloc[0]["id"]
    partial = ref_df[names.str.startswith(norm(first)) | names.str.contains(norm(first), regex=False)]
    if len(partial) == 1:
        log(case_ref, table, column, name, f"Matched to '{partial.iloc[0]['name']}'", "INFO")
        return partial.iloc[0]["id"]
    log(case_ref, table, column, name, f"{'No' if partial.empty else 'Several'} matching names in reference file, id left null")
    return None

