def created_date_for(case):
    for field in CREATED_DATE_SOURCES:
        value = dates_by_case.get(case["id"], {}).get(field)
        if blank(value):
            value = case.get(field)
        if not blank(value):
            return value, field
    return RUN_DATE, "run date"

INT_COLUMNS = {"siteEasting", "siteNorthing", "existingSpaces", "proposedSpaces", "bedroomsUnknown", "bedroomsOne",
               "bedroomsTwo", "bedroomsThree", "bedroomsFourPlus", "roomsLost", "roomsProposed", "netAdditionalRooms",
               "existingGross", "grossLost", "grossProposed", "netAdditionalGross"}
BOOL_COLUMNS = {"hasAgent", "hasSecondaryLpa", "eiaScreening", "eiaScreeningOutcome", "siteIsVisibleFromPublicLand",
                "isGreenBelt", "cilLiable", "bngExempt", "isWasteManagementDevelopment", "hasPreApplicationFee",
                "hasApplicationFee", "eligibleForFeeRefund", "hasResidentialUnitsChange", "hasExistingHousing",
                "hasProposedHousing", "hasNonResidentialFloorspaceChange", "hasRoomsChange"}

def as_int_text(v):
    if blank(v):
        return None
    try:
        return str(int(round(float(v))))
    except (TypeError, ValueError):
        return v

def as_bool_text(v):
    if blank(v):
        return None
    t = str(v).strip().lower()
    if t in ("true", "1", "1.0", "yes"):
        return "True"
    if t in ("false", "0", "0.0", "no"):
        return "False"
    return v

KEEP_EVEN_IF_INVALID = {"S62aCase", "ApplicationNote"}

id_to_ref = {c["id"]: c["reference"] for c in out["S62aCase"]}
frames, rejected = {}, []
for t, cols in SCHEMA.items():
    cols = cols.split()
    df = pd.DataFrame(out.get(t, []))
    for c in cols:
        if c not in df.columns:
            df[c] = None
    df = df[cols]
    for c in [c for c in cols if c in INT_COLUMNS]:
        df[c] = df[c].map(as_int_text)
    for c in [c for c in cols if c in BOOL_COLUMNS]:
        df[c] = df[c].map(as_bool_text)

    if t == "S62aCase":
        used = {}
        df["createdDate"] = df["createdDate"].astype(object)
        for i in df.index[df["createdDate"].map(blank)]:
            value, field = created_date_for(df.loc[i])
            df.at[i, "createdDate"] = value
            used[field] = used.get(field, 0) + 1
        for field, n in used.items():
            log(None, t, "createdDate", n, f"Empty in {n} row(s), filled from {field}", "INFO")
        if EXPECTED_SUBMISSION_FALLBACK:
            gap = df["expectedSubmissionDate"].map(blank)
            if gap.any():
                df["expectedSubmissionDate"] = df["expectedSubmissionDate"].astype(object)
                df.loc[gap, "expectedSubmissionDate"] = df.loc[gap, "createdDate"]
                log(None, t, "expectedSubmissionDate", int(gap.sum()),
                    f"Still empty in {int(gap.sum())} row(s), filled from createdDate", "INFO")
    if t == "ApplicationNote" and df["createdAt"].map(blank).any():
        case_created = ({c["id"]: c["createdDate"] for c in frames["S62aCase"].to_dict("records")}
                        if NOTE_CREATED_AT == "case" else {})
        n = int(df["createdAt"].map(blank).sum())
        df["createdAt"] = df["createdAt"].astype(object)
        df["createdAt"] = [v if not blank(v) else (case_created.get(s) or RUN_DATE)
                           for v, s in zip(df["createdAt"], df["s62aId"])]
        log(None, t, "createdAt", n, f"Empty in {n} row(s), filled from "
            f"{'the case createdDate' if NOTE_CREATED_AT == 'case' else 'the run date'}", "INFO")
    missing = pd.Series(False, index=df.index)
    for c in REQUIRED.get(t, []):
        miss = df[c].map(blank)
        if miss.any():
            fk = next((k for k in ("s62aCaseId", "s62aId") if k in df.columns), None)
            for i in df.index[miss]:
                ref = df.at[i, "reference"] if t == "S62aCase" else id_to_ref.get(df.at[i, fk]) if fk else None
                if t not in KEEP_EVEN_IF_INVALID:
                    rejected.append({"table": t, "caseReference": ref, "missing": c, **{"row_" + k: v for k, v in df.loc[i].items()}})
            summary_issue = f"Required field empty in {int(miss.sum())} row(s)" + (" - rows kept, will fail load until fixed"
                            if t in KEEP_EVEN_IF_INVALID else " - rows moved to _rejected.csv")
            log(None, t, c, int(miss.sum()), summary_issue)
        missing |= miss
    if t not in KEEP_EVEN_IF_INVALID:
        df = df[~missing]
    assert df["id"].is_unique, f"{t}: duplicate ids"
    frames[t] = df

